CAT = "ukc2Market"; SEG = "MKT"
Q = [
("MCOB 11.6.19 gives which as an example of market expectations of future interest rates?",
 "Bank of England forward rate", ["The lender's own forecast", "Last year's average Bank Rate", "The lender's standard variable rate"],
 "MCOB 11.6.19 names the forward sterling rate on the Bank of England website and says a lender should not use its own forecast."),
("Even if markets expect rates to fall, MCOB 11.6.18 says a lender must assume a five-year rise of at least:",
 "1%", ["0.5%", "2%", "3%"],
 "MCOB 11.6.18(3) requires a lender to assume rates rise by a minimum of 1% over the first five years, whatever market expectations suggest."),
("A lender need not stress future rates over five years when the mortgage rate is:",
 "Fixed for five years or more", ["Fixed for two years only", "A tracker with no floor", "Discounted for three years or more"],
 "MCOB 11.6.18(1) excludes contracts where the rate is fixed for five years or more from the start, or for the whole contract if shorter."),
("Besides market expectations, a lender's interest rate stress test must have regard to:",
 "Financial Policy Committee recommendations", ["The Monetary Policy Committee's latest minutes", "The borrower's own rate forecast", "The broker's view of the market"],
 "MCOB 11.6.18(2) requires regard to market expectations and any prevailing FPC recommendation on interest-rate stress tests."),
("Under PRA buy-to-let standards, the interest coverage ratio compares:",
 "Monthly rent with monthly interest", ["Loan size with property value", "Rent with the landlord's salary", "Interest with the borrower's savings"],
 "SS13/16 defines the ICR as expected monthly rental income from the property divided by monthly interest payments, allowing for likely rate rises."),
("Under PRA expectations, expected buy-to-let rent may be verified by:",
 "An independent qualified valuer", ["The borrower's own written estimate", "The seller's rental advert", "The broker's market view"],
 "SS13/16 says expected rent should be verified by a suitably qualified valuer independent of the borrower, an automated model or an existing rental agreement."),
("A building society is owned by:",
 "Its members", ["Its shareholders", "HM Treasury", "The Bank of England"],
 "Building societies are mutuals. Building Societies Act 1986 s5 says their principal purpose is loans secured on residential property funded substantially by members."),
("By law, a building society's principal purpose is making loans:",
 "Secured on homes and funded by members", ["To businesses, and funded by shareholders", "Unsecured, and funded by the markets", "To government, funded by deposits"],
 "Building Societies Act 1986 s5(1)(a): its purpose or principal purpose is loans secured on residential property and funded substantially by its members."),
("A lender funded mainly from wholesale money markets is most exposed to:",
 "Rising money market rates", ["Falling numbers of savers", "Higher stamp duty rates", "Lower house building rates"],
 "Wholesale funding is borrowed from other institutions at market rates, so the lender's costs rise when money market rates rise."),
("Under MCOB 11.6.18A, a second charge lender's rate stress must also consider:",
 "Rates on the existing first mortgage", ["Rates on the borrower's savings accounts", "Rates on the next owner's loan", "Rates on the borrower's pension"],
 "MCOB 11.6.18A requires a second charge lender to consider likely future rates on any regulated mortgage contract that remains in place, at least on its outstanding balance."),
("Under the Mortgage Charter, a borrower near the end of a fixed rate can lock in a new deal up to:",
 "Six months ahead", ["Two weeks ahead", "Three months ahead", "Twelve months ahead"],
 "The Mortgage Charter says customers can lock in a deal up to six months ahead, and ask for a better like-for-like deal until the new term starts."),
("Which body sets Bank Rate?",
 "The Monetary Policy Committee", ["The Financial Policy Committee", "The Prudential Regulation Authority", "The Financial Conduct Authority"],
 "Bank Rate is the Bank of England's main monetary policy tool, set by its Monetary Policy Committee to meet the inflation target."),
]
